# exact covers of target pixels by one 2x2 square + four L triominoes
cells={(0,1),(0,2),(0,4),(0,5),(1,0),(1,1),(1,2),(1,3),(1,4),(1,5),(2,1),(2,2),(2,4),(3,2),(3,3),(3,4)}
squares=[{(r,c) for r in range(rr,rr+2) for c in range(cc,cc+2)} for rr in range(3) for cc in range(6) if all((r,c) in cells for r in range(rr,rr+2) for c in range(cc,cc+2))]
Ls=[]
for r in range(3):
 for c in range(6):
  sq={(r,c),(r+1,c),(r,c+1),(r+1,c+1)}
  for miss in sq:
   L=sq-{miss}
   if L<=cells: Ls.append((L,miss))
solutions=[]
for S in squares:
 rem=cells-S
 def rec(rem,chosen):
  if not rem:
   if len(chosen)==4: solutions.append((S,chosen.copy()))
   return
  if len(chosen)>=4:return
  p=min(rem)
  for L,m in Ls:
   if p in L and L<=rem:
    rec(rem-L,chosen+[(L,m)])
 rec(rem,[])
len(solutions), squares
